module main
const max_input=256
fn store_le(mut output &u8,offset int,x i64){bits:=u64(x);for b in 0..8{output[offset+b]=u8((bits>>(b*8))&255)}}
@[export: 'unknown_sort']
pub fn unknown_sort(v &i64,n usize,mut output &u8,capacity usize) i64{unsafe{if v==nil||n>257{return -1}if n>max_input{return -1}mut work:=[max_input]i64{};mut starts:=[max_input]i64{};mut ends:=[max_input]i64{};mut result:=[max_input]i64{};for i in 0..int(n){work[i]=v[i]}mut count:=int(n);mut used:=0;mut end_count:=0;for count>1{mut min_i:=0;mut max_i:=0;for i in 1..count{if work[i]<work[min_i]{min_i=i};if work[i]>work[max_i]{max_i=i}}min_v:=work[min_i];max_v:=work[max_i];starts[used]=min_v;used++;ends[end_count]=max_v;end_count++;for i in min_i..count-1{work[i]=work[i+1]}count--;mut max_pos:=0;for max_pos<count&&work[max_pos]!=max_v{max_pos++}if max_pos==count{return -1}for i in max_pos..count-1{work[i]=work[i+1]}count--}mut out_n:=0;for i in 0..used{result[out_n]=starts[i];out_n++}for i in 0..count{result[out_n]=work[i];out_n++}mut i:=end_count;for i>0{i--;result[out_n]=ends[i];out_n++}bytes:=8*out_n;if output==nil||capacity<usize(bytes){return -2}for i in 0..out_n{store_le(mut output,8*i,result[i])}return i64(bytes)}}
